insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_art1_v1'
from (values
('117.302.c.1.A',2,'A student sketches a pair of old boots on a table while looking right at them. Which source of ideas is this?','["Direct observation", "A random guess", "A copied poster", "Imagination only"]'::jsonb,0,'Drawing from life uses direct observation.','original'),
('117.302.c.1.A',3,'An artist builds a painting from memories of her grandmother''s kitchen. Which source of ideas is she using?','["A copied photograph", "Experiences and imagination", "Only direct observation", "A required template"]'::jsonb,1,'Memories and imagination are personal sources.','original'),
('117.302.c.1.B',2,'Which of these is an element of art?','["Unity", "Emphasis", "Line", "Balance"]'::jsonb,2,'Line is an element; the others are principles.','original'),
('117.302.c.1.B',3,'A painter mixes blue with yellow to make green. Which element of art is she working with?','["Form", "Texture", "Space", "Color"]'::jsonb,3,'Mixing hues is working with color.','original'),
('117.302.c.1.C',2,'Which of these is a principle of design?','["Balance", "Shape", "Line", "Texture"]'::jsonb,0,'Balance is a principle; the others are elements.','original'),
('117.302.c.1.C',3,'A quilt repeats the same star shape in rows across the whole surface. Which principle of design is this?','["Emphasis only", "Repetition and pattern", "Proportion only", "Contrast only"]'::jsonb,1,'Repeating a motif creates pattern.','original'),
('117.302.c.1.D',3,'A viewer reads a painting of a stormy sea as a symbol of struggle. She is making a judgment about the artwork''s what?','["Paper weight", "Brush brand", "Expressive properties such as meaning and metaphor", "Frame price"]'::jsonb,2,'Meaning and metaphor are expressive properties.','original'),
('117.302.c.1.D',3,'Two students disagree about the message of a sculpture. What is the best way to support a judgment about its meaning?','["Count the pages in the book", "Say it is just their opinion", "Ignore the artwork", "Point to details such as subject, color and form as evidence"]'::jsonb,3,'Judgments rest on visible evidence.','original'),
('117.302.c.2.A',3,'A student must design a poster that clearly shows a recycling message. She tries three thumbnail sketches and picks the clearest. What is she doing?','["Solving a visual problem through trial and refinement", "Skipping planning", "Copying another poster", "Guessing"]'::jsonb,0,'Problem solving explores several options.','original'),
('117.302.c.2.A',3,'Drawing a still life using real fruit and a vase relies on which problem-solving approach?','["Pure imagination", "Direct observation", "Random marks", "Tracing"]'::jsonb,1,'Observation solves proportion and shading.','original'),
('117.302.c.2.B',3,'A graphic designer, an architect and a potter each solve problems with design. This shows that design solutions are used in what?','["Only museums", "Only schools", "A variety of applications and careers", "Only paintings"]'::jsonb,2,'Design applies broadly.','original'),
('117.302.c.2.B',3,'A designer plans a chair that is both comfortable and attractive. This is an example of balancing what?','["Time and distance", "Cost and weather", "Noise and color", "Function and visual appearance"]'::jsonb,3,'Design solutions meet needs and look good.','original'),
('117.302.c.2.C',3,'An artist wants to use a photograph from the internet in her collage. What should she understand about copyright?','["Copyrighted images generally need permission or must be transformed within the law", "Copyright does not apply to students", "All internet images are free", "Only paintings are protected"]'::jsonb,0,'Copyright protects creators'' work.','original'),
('117.302.c.2.C',3,'Which type of work can an artist use freely because its copyright has expired?','["A new copyrighted photo", "A work in the public domain", "A current album cover", "A licensed logo"]'::jsonb,1,'Public domain works are free to use.','original'),
('117.302.c.2.D',3,'A student paints a bright, swirling sky to show how excited she felt at a concert. She is using art to do what?','["Follow a recipe", "Measure time", "Communicate thoughts, feelings or impressions", "Record a map"]'::jsonb,2,'Original artwork can express feelings.','original'),
('117.302.c.2.D',3,'What makes an artwork original?','["It is copied from a poster", "It uses no color", "It is traced from a photo", "It comes from the artist''s own ideas rather than copying another work"]'::jsonb,3,'Originality means personal ideas.','original'),
('117.302.c.2.E',3,'A class paints a large mural, with each student designing one section that fits the theme. This is an example of what?','["Collaboration to create a work of art", "Copying", "Tracing", "Working alone"]'::jsonb,0,'Many hands share the project.','original'),
('117.302.c.2.E',3,'What is an important skill when collaborating on an artwork?','["Ignoring teammates", "Listening to others'' ideas and agreeing on a plan", "Changing others'' work without asking", "Working in secret"]'::jsonb,1,'Collaboration needs communication.','original'),
('117.302.c.2.F',2,'Which tool is best for creating a printmaking plate?','["A pencil only", "A glue stick only", "A linoleum cutter and a block", "A paint roller only"]'::jsonb,2,'Cutters carve plates for printing.','original'),
('117.302.c.2.F',3,'A sculptor adds clay to a form and then smooths it. Which process is she using?','["Weaving", "Printmaking", "Photography", "Modeling"]'::jsonb,3,'Adding and shaping clay is modeling.','original'),
('117.302.c.3.A',3,'A student compares a Renaissance portrait with a modern digital portrait. Which question helps compare them?','["How do the styles, materials and themes differ?", "Which has a longer title?", "Which is heavier?", "Which is older by weight?"]'::jsonb,0,'Comparing looks at style, materials and themes.','original'),
('117.302.c.3.A',3,'A recurring theme in both ancient and modern art is what?','["Only advertising", "The human figure and nature", "Only abstract lines", "Only computers"]'::jsonb,1,'Common themes appear across time.','original'),
('117.302.c.3.B',3,'Navajo weaving, Japanese woodblock prints and West African masks are examples of artwork from different what?','["Grades", "Seasons", "Cultures", "Sports"]'::jsonb,2,'Art reflects cultural traditions.','original'),
('117.302.c.3.B',3,'Artworks from different cultures often reflect what about their makers?','["Only prices", "Only birthdays", "Only weather forecasts", "Beliefs, values and environment"]'::jsonb,3,'Art reflects the culture.','original'),
('117.302.c.3.C',3,'A group creates a community mural on a library wall. This is a community-based art project because it does what?','["Connects artwork to the people and place it serves", "Is kept private", "Is hidden in a closet", "Is sold for profit only"]'::jsonb,0,'Community art serves the public.','original'),
('117.302.c.3.C',3,'Which is a benefit of a community-based art project?','["It removes public places", "It brings people together and beautifies a shared space", "It isolates people", "It prevents all art"]'::jsonb,1,'Community art builds connection.','original'),
('117.302.c.3.D',3,'A person who paints on weekends but works in a bank is pursuing art as what?','["A required class", "A full-time career", "An avocation", "A prize"]'::jsonb,2,'An avocation is a hobby alongside a career.','original'),
('117.302.c.3.D',3,'Which is a career in art?','["Mail sorter", "Farmhand only", "Cashier only", "Graphic designer"]'::jsonb,3,'Graphic design is an art career.','original'),
('117.302.c.4.A',3,'A student explains why she used dark blue in her self-portrait. She is doing what?','["Justifying an artistic decision", "Ignoring the process", "Hiding her work", "Avoiding feedback"]'::jsonb,0,'Justifying choices explains the artwork.','original'),
('117.302.c.4.A',3,'Which statement is a helpful peer evaluation?','["It is bad", "The overlapping shapes create depth, but the background feels flat", "Whatever", "I don''t like it"]'::jsonb,1,'Specific, balanced feedback is useful.','original'),
('117.302.c.4.B',3,'A four-step critique uses description, analysis, interpretation and what?','["Guessing", "Hiding", "Evaluation", "Subtraction"]'::jsonb,2,'The final step is evaluation.','original'),
('117.302.c.4.B',3,'During the description step of a critique, a student should do what?','["Compare it to a friend''s work", "Say whether it is good", "Guess the price", "Name what she sees without judging"]'::jsonb,3,'Description states observable facts.','original'),
('117.302.c.4.C',3,'A student chooses her best five pieces for a portfolio and writes a note about why each was selected. What is she doing?','["Evaluating and analyzing her own work to construct a portfolio", "Throwing work away", "Copying others", "Skipping reflection"]'::jsonb,0,'Portfolios show selected work and reflection.','original'),
('117.302.c.4.C',3,'A digital portfolio is useful because it does what?','["Removes the need for art", "Lets an artist share work online and show growth over time", "Hides her art", "Prevents critique"]'::jsonb,1,'Electronic portfolios are easy to share.','original'),
('117.302.c.4.D',3,'A student visits a gallery exhibition and writes a conclusion about how the artist uses color to create mood. She is doing what?','["Counting frames", "Guessing", "Analyzing artwork to form precise conclusions", "Ignoring the exhibition"]'::jsonb,2,'Analysis supports conclusions with evidence.','original'),
('117.302.c.4.D',3,'Which evidence best supports a conclusion about an artist''s style?','["The size of the signature only", "The weather at the exhibit", "A friend''s opinion only", "Repeated use of similar colors, shapes and techniques across several works"]'::jsonb,3,'Patterns across works support a conclusion.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
